function search(arr, target) {
  let lo = 0, hi = arr.length;
  // invariant: if target is in arr, its index is in [lo, hi)
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) lo = mid;   // was: mid + 1
    else hi = mid;
  }
  return -1;
}

