// PR description:
// Claim: max(list) returns the largest element of any non-empty list.
// Proof: assume max is correct FOR ALL non-empty lists.
// Then for a list of length n, max returns the larger of list[0]
// and max(tail), which is correct. QED.

function max(list) {
  if (list.length === 1) return list[0];
  const m = max(list.slice(1));
  return list[0] > m ? list[0] : m;
}

evidence.ru:
// Описание PR:
// Утверждение: max(list) возвращает наибольший элемент любого непустого списка.
// Доказательство: допустим, что max корректна ДЛЯ ВСЕХ непустых списков.
// Тогда для списка длины n max возвращает большее из list[0]
// и max(tail), что корректно. Что и требовалось.

function max(list) {
  if (list.length === 1) return list[0];
  const m = max(list.slice(1));
  return list[0] > m ? list[0] : m;
}
